#!/bin/sh
# Regenerates Shared/Generated/nylon_ipc.pb.swift from the nylon repo's protocol/nylon_ipc.proto (the submodule, or
# $NYLON_DIR). Run it after updating the submodule: the build fails until the generated file matches the proto.
# protoc-gen-swift is built from the SwiftProtobuf version Package.resolved pins, so the code matches the library the
# app links. protoc is the one nylon's own Go code needs.
set -eu
cd "$(dirname "$0")/.."

nylon=${NYLON_DIR:-nylon}
proto=$nylon/protocol/nylon_ipc.proto
version=$(python3 -c 'import json, sys
print(next(p["state"]["version"] for p in json.load(open(sys.argv[1]))["pins"] if p["identity"] == "swift-protobuf"))' \
    nylon.xcodeproj/project.xcworkspace/xcshareddata/swiftpm/Package.resolved)

src=build/swift-protobuf-$version
plugin=$src/.build/release/protoc-gen-swift
if [ ! -x "$plugin" ]; then
    rm -rf "$src"
    git clone --quiet --depth 1 --branch "$version" https://github.com/apple/swift-protobuf.git "$src"
    swift build --package-path "$src" -c release --product protoc-gen-swift
fi

out=$(mktemp -d)
trap 'rm -rf "$out"' EXIT
protoc --plugin=protoc-gen-swift="$plugin" --swift_out="$out" -I "$nylon/protocol" nylon_ipc.proto
mkdir -p Shared/Generated
{
    # scripts/check-proto.sh compares this hash with the proto's
    printf '// Generated by scripts/proto.sh from nylon/protocol/nylon_ipc.proto, sha256 %s. Do not edit.\n\n' \
        "$(shasum -a 256 "$proto" | cut -d' ' -f1)"
    cat "$out/nylon_ipc.pb.swift"
} >Shared/Generated/nylon_ipc.pb.swift
echo "wrote Shared/Generated/nylon_ipc.pb.swift (SwiftProtobuf $version)"
